  const cleaned = fromEmail.replace(/[^a-zA-Z0-9À-ž ._'-]/g, ' ').replace(/\s+/g, ' ').trim();
  return (cleaned || 'Customer PT Dincorp Inovasi Asia').slice(0, 120);
