  if (fresh.length >= limit) {
    const oldest = fresh[0] || now;
    return { ok: false, retryAfterMs: Math.max(1000, windowMs - (now - oldest)) };
  }
  fresh.push(now);
  CUSTOMER_SECURITY_RATE_LIMIT_STORE.set(key, fresh);

  return { ok: true };
