    DIRAC_PASSKEY_A2F_CHALLENGE_STORE,
    jti,
    record,
    DIRAC_PASSKEY_A2F_CHALLENGE_STORE_MAX_V321,
    now,
    (value) => Number(value && value.expiresAtMs || 0)
