      patch: DIRAC_PASSKEY_SIGNED_AUTHORITY_V304,
      binding: String(binding),
      expiresAt: Number(strictSigned.exp),
      remainingTtlSeconds,
      sessionId: String(strictSigned.sessionId),
      securityEpoch: epoch
