  const ctx = diracPasskeyRefreshEscrowGuardContextV250(req, 'dirac_mfa_passkey_verify');
  let sealed = null;
  try { sealed = req && req[DIRAC_PASSKEY_REFRESH_ESCROW_CACHE_V250] || null; } catch (_) { sealed = null; }
