function diracUniversalPesananNormalizeRequestedType(value) {
  const clean = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (clean === 'domain' || clean === 'domain_order' || clean === 'domain_orders') return 'domain';
  if (clean === 'regular' || clean === 'standard' || clean === 'standard_order' || clean === 'orders') return 'regular';
  return '';
}

async function diracUniversalPesananFindOwnedOrder(inputOrderId, requestedType, customerId) {
  if (requestedType === 'domain') return diracUniversalPesananFetchOwnedDomainOrder(inputOrderId, customerId);
  return diracUniversalPesananFindOwnedRegularAcrossDatabases(inputOrderId, customerId);
}

async function diracUniversalPesananFindOwnedRegularAcrossDatabases(inputOrderId, customerId) {
  const commerce = await diracUniversalPesananFetchOwnedRegularOrder(inputOrderId, customerId, 'commerce');
  const security = await diracUniversalPesananFetchOwnedRegularOrder(inputOrderId, customerId, 'security');
  if (commerce.ok && security.ok) {
    return { ok: false, status: 409, message: 'Order regular ambigu di dua database. Payment dihentikan secara aman.' };
  }
  if ((commerce.ok && security.status >= 500) || (security.ok && commerce.status >= 500)) {
    return { ok: false, status: 503, message: 'Sumber database order belum dapat diverifikasi secara lengkap.' };
  }
  if (commerce.ok) return commerce;
  if (security.ok) return security;
  if (commerce.status >= 500) return commerce;
  if (security.status >= 500) return security;
  if (commerce.status === 400 && security.status === 400) return commerce;
  return { ok: false, status: 404, message: 'Order regular tidak ditemukan atau bukan milik akun ini.' };
}

async function diracUniversalPesananFetchOwnedRegularOrder(inputOrderId, customerId, database = 'commerce') {
  const clean = lockedPaymentCleanText(inputOrderId, 140);
  const filters = [];
  if (customerSecurityLooksLikeUuid(clean)) filters.push(`id.eq.${clean}`);
  if (clean) filters.push(`order_id.eq.${clean}`);

  if (!filters.length) return { ok: false, status: 400, message: 'Order ID regular tidak valid.' };

  const select = 'id,order_id,customer_id,customer_name,customer_email,customer_phone,service_type,subtotal,total,payment_method,payment_status,order_status,created_at';
  const path = '/rest/v1/orders?select=' + encodeURIComponent(select)
    + '&customer_id=eq.' + encodeURIComponent(customerId)
    + '&or=' + encodeURIComponent(`(${filters.join(',')})`)
    + '&limit=1';

  const orderDatabase = diracRegularOrderDatabaseV443(database);
  const result = await supabaseFetch(path, { method: 'GET', auth: 'service', db: orderDatabase });
  if (!result.ok) return { ok: false, status: result.status || 500, message: 'Gagal membaca order regular.' };
  const rows = Array.isArray(result.data) ? result.data : [];
  if (rows.length > 1) return { ok: false, status: 409, message: 'Order regular tidak unik.' };
  const row = rows[0] || null;
  if (!row || !row.id) return { ok: false, status: 404, message: 'Order regular tidak ditemukan atau bukan milik akun ini.' };
  return { ok: true, kind: 'regular', database: orderDatabase, order: row };
}

async function diracUniversalPesananFetchOwnedDomainOrder(inputOrderId, customerId) {
  return { ok: false, status: 410, code: 'DOMAIN_ORDERS_RETIRED', retired: true, message: 'Layanan pesanan domain telah dinonaktifkan.' };
}

async function diracUniversalPesananBuildPaymentInput(lookup, customer, userEmail) {
  if (!lookup || !lookup.ok || !lookup.order) return { ok: false, status: 404, message: 'Order tidak ditemukan.' };
  if (lookup.kind === 'domain') return diracUniversalPesananBuildDomainPaymentInput(lookup.order, customer, userEmail);
  return diracUniversalPesananBuildRegularPaymentInput(lookup.order, customer, userEmail, lookup.database);
}

async function diracUniversalPesananBuildRegularPaymentInput(order, customer, userEmail, database = 'commerce') {
  const orderId = String(order.id || '').trim();
  const orderCode = lockedPaymentCleanText(order.order_id || orderId, 100);
  const serviceType = lockedPaymentNormalizeServiceType(order.service_type || 'order');
  const amount = lockedPaymentMoney(order.total);
  const subtotal = lockedPaymentMoney(order.subtotal);
  const paymentStatus = lockedPaymentStatus(order.payment_status);
  const orderStatus = lockedPaymentStatus(order.order_status);

  if (!customerSecurityLooksLikeUuid(orderId)) return { ok: false, status: 409, message: 'Order ID database tidak valid.' };
  if (!diracUniversalPesananCanPayByStatus(paymentStatus, orderStatus, amount)) {
    return { ok: false, status: 409, message: `Order belum bisa dibayar. Status pembayaran: ${paymentStatus}, status order: ${orderStatus}.` };
  }

  const orderDatabase = diracRegularOrderDatabaseV443(database);
  const itemPack = await diracUniversalPesananFetchRegularItems(orderId, amount, serviceType, false, orderDatabase);
  if (subtotal <= 0 || itemPack.totalItem !== subtotal) return { ok: false, status: 409, message: 'Subtotal rincian order tidak cocok dengan database.' };
  return {
    ok: true,
    kind: 'regular',
    orderDatabase,
    orderId,
    domainOrderId: null,
    orderRefId: orderId,
    orderCode,
    referencePrefix: 'ORD',
    serviceType,
    amount,
    amountSource: 'orders.total.database',
    itemTotal: itemPack.totalItem,
    customer: {
      name: lockedPaymentCleanText(order.customer_name || customer.name || userEmail, 120),
      email: normalizeAuthEmail(order.customer_email || customer.email || userEmail),
      phone: lockedPaymentCleanText(order.customer_phone || customer.phone || '', 80)
    },
    items: itemPack.items
  };
}

async function diracUniversalPesananBuildDomainPaymentInput(order, customer, userEmail) {
  const domainOrderId = String(order.id || '').trim();
  const orderCode = lockedPaymentCleanText(order.id || domainOrderId, 100);
  const amount = lockedPaymentMoney(order.total_price || 0);
  const paymentStatus = lockedPaymentStatus(order.payment_status);
  const orderStatus = lockedPaymentStatus(order.order_status || order.status);

  if (!customerSecurityLooksLikeUuid(domainOrderId)) return { ok: false, status: 409, message: 'Domain order ID database tidak valid.' };
  if (!diracUniversalPesananCanPayByStatus(paymentStatus, orderStatus, amount)) {
    return { ok: false, status: 409, message: `Domain order belum bisa dibayar. Status pembayaran: ${paymentStatus}, status order: ${orderStatus}.` };
  }

  const itemPack = await diracUniversalPesananFetchDomainItems(domainOrderId, amount, order.domain_name);
  if (itemPack.totalItem !== amount) return { ok: false, status: 409, message: 'Rincian nominal domain tidak cocok dengan database.' };
  return {
    ok: true,
    kind: 'domain',
    orderDatabase: 'domain',
    orderId: null,
    domainOrderId,
    orderRefId: domainOrderId,
    orderCode: 'DOM-' + domainOrderId.slice(0, 8).toUpperCase(),
    referencePrefix: 'DOM',
    serviceType: 'domain',
    amount,
    amountSource: 'domain_orders.total_price.database',
    itemTotal: itemPack.totalItem,
    customer: {
      name: lockedPaymentCleanText(order.customer_name || customer.name || userEmail, 120),
      email: normalizeAuthEmail(order.customer_email || order.owner_email || customer.email || userEmail),
      phone: lockedPaymentCleanText(order.customer_whatsapp || customer.phone || '', 80)
    },
    items: itemPack.items
  };
}

async function diracUniversalPesananFetchRegularItems(orderId, amount, serviceType, includePresentation = true, database = 'commerce') {
  const orderDatabase = diracRegularOrderDatabaseV443(database);
  const select = 'id,order_id,product_doc_id,product_title,quantity,unit_price,cost_price';
  const path = '/rest/v1/order_items?select=' + encodeURIComponent(select) + '&order_id=eq.' + encodeURIComponent(orderId);
  const itemOptions = orderDatabase === 'security'
    ? { method: 'GET', auth: 'service', db: 'security' }
    : { method: 'GET', auth: 'service' };
  const result = await supabaseFetch(path, itemOptions).catch(() => null);
  const rows = result && result.ok && Array.isArray(result.data) ? result.data : [];
  if (!result || result.ok !== true || rows.length === 0) throw Object.assign(new Error('PAYMENT_ITEMS_UNAVAILABLE'), { statusCode: 503 });
  // Payment uses the locked item title, quantity and price. Presentation-only
  // product details remain available to invoice/email consumers; a missing
  // stored title still resolves through the original product-title fallback.
  const productRows = includePresentation === false
    ? rows.filter((row) => !lockedPaymentCleanText(row && row.product_title || '', 180))
    : rows;
  const productsById = productRows.length
    ? await diracUniversalPesananFetchProductsForOrderItems(productRows)
    : new Map();
  const items = [];
  let total = 0;
  const laboratoryImageTarget = orderDatabase === 'security' && lockedPaymentNormalizeServiceType(serviceType) === 'laboratorium'
    ? diracAppOriginHandoffTargetV313('laboratorium')
    : null;

  rows.forEach((row, index) => {
    const productKey = lockedPaymentCleanText(row && row.product_doc_id || '', 120);
    const laboratoryProductId = laboratoryImageTarget
      ? sessionOwnershipCheckoutNormalizeLaboratoryProductIdV443(productKey)
      : 0;
    const product = productsById.get(productKey) || {};
    const quantity = Number(row && row.quantity);
    const unitPrice = lockedPaymentMoney(row && row.unit_price);
    const title = lockedPaymentCleanText(row && row.product_title || product.title || product.name || myOrdersServiceLabel(serviceType) || 'Item pesanan', 180);
    if (!title || !Number.isSafeInteger(quantity) || quantity <= 0 || quantity > 9999 || unitPrice <= 0) throw Object.assign(new Error('PAYMENT_ITEMS_INVALID'), { statusCode: 409 });
    const subtotal = quantity * unitPrice;
    total += subtotal;
    items.push({
      id: String(row.id || `item-${index + 1}`),
      product_doc_id: productKey || null,
      title,
      quantity,
      unit_price: unitPrice,
      subtotal,
      image_url: laboratoryProductId
        ? orderMailProductAssetUrl(productKey, laboratoryImageTarget.origin + '/lb' + laboratoryProductId + '.webp')
        : orderMailProductAssetUrl(productKey, product.image_url || product.img || ''),
      description: orderMailCleanText(product.description || product.notes || product.long_description || product.category || '', 220),
      category: orderMailCleanText(product.category || '', 80),
      fragrance_type: orderMailCleanText(product.fragrance_type || '', 80)
    });
  });

  if (!Number.isSafeInteger(total) || total <= 0) throw Object.assign(new Error('PAYMENT_ITEMS_INVALID'), { statusCode: 409 });

  return { items, totalItem: total };
}

async function diracUniversalPesananFetchProductsForOrderItems(rows) {
  const ids = Array.from(new Set((rows || [])
    .map((row) => lockedPaymentCleanText(row && row.product_doc_id || '', 120))
    .filter(Boolean)));
  const productsById = new Map();
  for (const id of ids) {
    const result = await diracProductsJsonReadV601('invoice', id).catch(() => null);
    const product = result && result.ok && Array.isArray(result.data) ? result.data[0] : null;
    if (product) {
      if (product.doc_id) productsById.set(lockedPaymentCleanText(product.doc_id, 120), product);
      if (product.firebase_id) productsById.set(lockedPaymentCleanText(product.firebase_id, 120), product);
      productsById.set(id, product);
    }
  }
  return productsById;
}

async function diracUniversalPesananFetchDomainItems(domainOrderId, amount, fallbackDomainName) {
  const select = 'id,order_id,domain_name,extension,years,register_price,subtotal';
  const path = '/rest/v1/domain_order_items?select=' + encodeURIComponent(select) + '&order_id=eq.' + encodeURIComponent(domainOrderId);
  const result = await supabaseFetch(path, { method: 'GET', auth: 'service' }).catch(() => null);
  const rows = result && result.ok && Array.isArray(result.data) ? result.data : [];
  if (!result || result.ok !== true || rows.length === 0) throw Object.assign(new Error('DOMAIN_PAYMENT_ITEMS_UNAVAILABLE'), { statusCode: 503 });
  const items = [];
  let total = 0;

  rows.forEach((row, index) => {
    const quantity = Number(row && row.years);
    const subtotal = lockedPaymentMoney(row && (row.subtotal || row.register_price));
    const unitPrice = quantity > 0 ? Math.max(1, Math.round(subtotal / quantity)) : subtotal;
    const title = lockedPaymentCleanText(row && row.domain_name || fallbackDomainName || 'Domain order', 180);
    if (!title || !Number.isSafeInteger(quantity) || quantity <= 0 || quantity > 10 || unitPrice <= 0) throw Object.assign(new Error('DOMAIN_PAYMENT_ITEMS_INVALID'), { statusCode: 409 });
    total += unitPrice * quantity;
    items.push({
      id: String(row.id || `domain-${index + 1}`),
      domain_name: title,
      title,
      quantity,
      unit_price: unitPrice,
      price: unitPrice,
      subtotal: unitPrice * quantity
    });
  });

  if (!Number.isSafeInteger(total) || total <= 0 || total !== midtransStrictMoneyV350(amount)) throw Object.assign(new Error('DOMAIN_PAYMENT_TOTAL_MISMATCH'), { statusCode: 409 });

  return { items, totalItem: total };
}

function diracUniversalPesananCanPayByStatus(paymentStatus, orderStatus, amount) {
  const pay = lockedPaymentStatus(paymentStatus);
  const order = lockedPaymentStatus(orderStatus);
  if (lockedPaymentMoney(amount) <= 0) return false;
  if (['paid', 'success', 'settled', 'settlement', 'capture', 'refunded'].includes(pay)) return false;
  if (['completed', 'cancelled', 'canceled', 'failed', 'expired', 'refunded'].includes(order)) return false;
  return ['unpaid', 'pending', 'pending_payment', 'created'].includes(pay)
    && ['unpaid', 'pending', 'pending_payment', 'created'].includes(order);
}

function diracUniversalPesananOrderCanPay(order) {
  if (!order) return false;
  return diracUniversalPesananCanPayByStatus(order.payment_status, order.order_status, order.total);
}

async function diracUniversalPesananFindReusableTransaction(input) {
  const customerId = String(input && input.customerId || '').trim();
  const amount = lockedPaymentMoney(input && input.amount);
  const isDomain = input && input.kind === 'domain';
  const orderDatabase = isDomain ? 'domain' : diracRegularOrderDatabaseV443(input && input.orderDatabase);
  const orderId = String(isDomain ? input.domainOrderId : input.orderId || '').trim();

  if (!customerSecurityLooksLikeUuid(customerId) || !customerSecurityLooksLikeUuid(orderId) || amount <= 0) {
    return { ok: true, transaction: null };
  }

  const column = isDomain ? 'domain_order_id' : 'order_id';
  const select = 'id,order_id,domain_order_id,customer_id,service_type,gateway_name,gateway_reference,payment_status,amount,currency,payment_url,expired_at,created_at,metadata';
  const statuses = ['unpaid', 'pending', 'created'].join(',');
  const path = '/rest/v1/payment_transactions?select=' + encodeURIComponent(select)
    + '&' + column + '=eq.' + encodeURIComponent(orderId)
    + '&customer_id=eq.' + encodeURIComponent(customerId)
    + '&amount=eq.' + encodeURIComponent(String(amount))
    + '&payment_status=in.(' + statuses + ')'
    + '&order=created_at.desc&limit=8';

  const result = await supabaseFetch(path, { method: 'GET', auth: 'service', db: 'paymentService' }).catch(() => null);
  if (!result || !result.ok) return { ok: false, status: result && result.status || 500 };

  const rows = Array.isArray(result.data) ? result.data : [];
  const now = Date.now();
  const reusable = rows.find((row) => {
    if (!row || diracPaymentTransactionOrderDatabaseV443(row, isDomain ? 'domain' : 'regular') !== orderDatabase
        || !midtransTrustedPaymentUrlV352(row.payment_url)
        || row.gateway_name !== 'midtrans' || row.currency !== 'IDR'
        || String(row.customer_id || '') !== customerId
        || String(isDomain ? row.domain_order_id || '' : row.order_id || '') !== orderId
        || Boolean(row.order_id) === Boolean(row.domain_order_id)
        || midtransStrictMoneyV350(row.amount) !== amount
        || !['unpaid', 'pending', 'created'].includes(String(row.payment_status || ''))) return false;
    if (!row.expired_at) return true;
    const expires = new Date(row.expired_at).getTime();
    return Number.isFinite(expires) && expires > now;
  });

  return { ok: true, transaction: reusable || null };
}


/* ============================================================
   ORDER EMAIL NOTIFICATION - APPEND ONLY - v13
   Scope:
   - Order notification email only.
   - Does not read or modify SMTP_USER/SMTP_PASS used by admin panel.
   - Does not touch login/hash/A2F/passkey/cookies/payment security.
   - Customer email uses ORDER_CUSTOMER_* ENV.
   - Owner/store email uses ORDER_OWNER_* ENV.
   ============================================================ */

const DIRAC_ORDER_MAIL_PATCH = 'order-mail-v24-paid-corporate-recovery-theme-email-only';
const __diracOrderMailPreviousHandler = __diracV202DispatcherSentinel;

__diracV202RegisterMiddleware(async function diracOrderMailWrapper(req, res, nextHandlerV202) {
  const rawAction = String((req.query && req.query.action) || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (rawAction !== 'order_mail_health' && rawAction !== 'order_email_health') {
    return nextHandlerV202(req, res);
  }

  const cors = setCors(req, res, { isDomainAction: true });
  if (req.method === 'OPTIONS') return res.status(cors.allowed ? 200 : 403).end();
  if (!cors.allowed) return res.status(403).json({ ok: false, message: 'Origin tidak diizinkan.' });
  if (req.method !== 'GET') return res.status(405).json({ ok: false, message: 'Gunakan GET.' });

  return res.status(200).json({
    ok: true,
    service: 'dirac-order-mail',
    ready: Boolean(orderMailSmtpConfig('customer').configured && orderMailSmtpConfig('owner').configured)
  });
}, "diracOrderMailWrapper");


const DIRAC_PAID_MAIL_TIMING_DIAGNOSTIC_V371 = 'dirac-paid-mail-timing-diagnostic-v371';

function diracPaidMailTimingCreateV371(req) {
  const now = Date.now();
  const requestId = String(req && req.__diracCentralRequestIdV211 || '');
  return {
    patch: DIRAC_PAID_MAIL_TIMING_DIAGNOSTIC_V371,
    request_id: /^[a-f0-9]{32}$/.test(requestId) ? requestId : '',
    webhook_received: now,
    payment_verified: 0,
    order_paid: 0,
    mail_start: 0,
    provider_accepted: 0,
    mail_complete: 0,
    first_provider: '',
    first_role: '',
    customer_provider: '',
    customer_provider_accepted: 0,
    owner_provider: '',
    owner_provider_accepted: 0,
    emitted: false
  };
}

function diracPaidMailTimingMarkV371(timing, marker) {
  if (!timing || timing.emitted === true) return;
  const now = Date.now();
  if (marker === 'payment_verified' && !timing.payment_verified) timing.payment_verified = now;
  else if (marker === 'order_paid' && !timing.order_paid) timing.order_paid = now;
  else if (marker === 'mail_start' && !timing.mail_start) timing.mail_start = now;
  else if (marker === 'mail_complete' && !timing.mail_complete) timing.mail_complete = now;
}

function diracPaidMailTimingProviderAcceptedV371(diagnostic, provider) {
  const timing = diagnostic && diagnostic.timing;
  const role = String(diagnostic && diagnostic.role || '');
  if (!timing || timing.emitted === true || (role !== 'customer' && role !== 'owner')) return;
  const now = Date.now();
  const cleanProvider = orderMailCleanText(provider || 'unknown', 32) || 'unknown';
  if (!timing.provider_accepted) {
    timing.provider_accepted = now;
    timing.first_provider = cleanProvider;
    timing.first_role = role;
  }
  if (role === 'customer' && !timing.customer_provider_accepted) {
    timing.customer_provider_accepted = now;
    timing.customer_provider = cleanProvider;
  } else if (role === 'owner' && !timing.owner_provider_accepted) {
    timing.owner_provider_accepted = now;
    timing.owner_provider = cleanProvider;
  }
}

function diracPaidMailTimingIsoV371(value) {
  return Number.isFinite(Number(value)) && Number(value) > 0 ? new Date(Number(value)).toISOString() : null;
}

function diracPaidMailTimingDeltaV371(end, start) {
  const a = Number(end || 0);
  const b = Number(start || 0);
  return a > 0 && b > 0 && a >= b ? Math.min(86400000, a - b) : null;
}

function diracPaidMailTimingEmitV371(req, timing, notification) {
  if (!timing || timing.emitted === true) return;
  timing.emitted = true;
  const requestId = String(req && req.__diracCentralRequestIdV211 || timing.request_id || '');
  const safeRequestId = /^[a-f0-9]{32}$/.test(requestId) ? requestId : '';
  const customerSent = Boolean(notification && notification.customer && notification.customer.sent === true);
  const ownerSent = Boolean(notification && notification.owner && notification.owner.sent === true);
  const payload = {
    v: DIRAC_PAID_MAIL_TIMING_DIAGNOSTIC_V371,
    request_id: safeRequestId,
    timeline_complete: Boolean(timing.webhook_received && timing.payment_verified && timing.order_paid && timing.mail_start && timing.provider_accepted && timing.mail_complete),
    timestamps: {
      webhook_received: diracPaidMailTimingIsoV371(timing.webhook_received),
      payment_verified: diracPaidMailTimingIsoV371(timing.payment_verified),
      order_paid: diracPaidMailTimingIsoV371(timing.order_paid),
      mail_start: diracPaidMailTimingIsoV371(timing.mail_start),
      provider_accepted: diracPaidMailTimingIsoV371(timing.provider_accepted),
      mail_complete: diracPaidMailTimingIsoV371(timing.mail_complete)
    },
    elapsed_ms: {
      webhook_to_payment_verified: diracPaidMailTimingDeltaV371(timing.payment_verified, timing.webhook_received),
      payment_verified_to_order_paid: diracPaidMailTimingDeltaV371(timing.order_paid, timing.payment_verified),
      order_paid_to_mail_start: diracPaidMailTimingDeltaV371(timing.mail_start, timing.order_paid),
      mail_start_to_provider_accepted: diracPaidMailTimingDeltaV371(timing.provider_accepted, timing.mail_start),
      provider_accepted_to_mail_complete: diracPaidMailTimingDeltaV371(timing.mail_complete, timing.provider_accepted),
      webhook_to_mail_complete: diracPaidMailTimingDeltaV371(timing.mail_complete, timing.webhook_received)
    },
    provider: {
      first: timing.first_provider || null,
      first_role: timing.first_role || null,
      customer: timing.customer_provider || null,
      customer_accepted_at: diracPaidMailTimingIsoV371(timing.customer_provider_accepted),
      owner: timing.owner_provider || null,
      owner_accepted_at: diracPaidMailTimingIsoV371(timing.owner_provider_accepted)
    },
    result: {
      ok: Boolean(notification && notification.ok === true),
      customer_sent: customerSent,
      owner_sent: ownerSent
    },
    privacy: 'no_email_no_uuid_no_order_id_no_token_no_cookie_no_secret'
  };
  try { console.info('[dirac-paid-mail-timing-v371] ' + JSON.stringify(payload)); } catch (_) {}
}

async function diracPaidMailTimingRunV371(req, timing, input) {
  diracPaidMailTimingMarkV371(timing, 'mail_start');
  let result = null;
  try {
    result = await orderMailNotifyPaidOrderFromPaymentSafe({ ...input, diagnosticTimingV371: timing });
    return result;
  } finally {
    diracPaidMailTimingMarkV371(timing, 'mail_complete');
    diracPaidMailTimingEmitV371(req, timing, result);
  }
}

